// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Maximum displacement per physics sub-step. Kept below BRICK_H + 2 * BALL_R
// (34 px), the minimum distance a ball must travel to jump over a brick
// entirely: at level 6 a capped frame (710 px/s × 50 ms) moves 35.5 px and
// would tunnel straight through a brick without this sweep (ISSUES.md #1,
// "tunnelling").
const MAX_STEP = 16;

// Advances the ball by a time step `dt` (in seconds). The move is swept in
// sub-steps so a fast ball cannot jump over a brick between two frames, and
// each sub-step handles bounces off the walls, the paddle AND the bricks
// (bricks bounce now — #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const speed = Math.hypot(ball.vx, ball.vy);
  const subSteps = Math.max(1, Math.ceil((speed * dt) / MAX_STEP));
  const h = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: destroy what the ball touches, bounce exactly once, score.
    const hit = brickHit(ball, state.bricks);
    for (const brick of hit) {
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

