// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — that is resolved per face in `bounceOff` (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision & bounce (pure, tested) -------------------------------

// Resolves the ball against every live brick it overlaps. Destroys each
// touched brick and bounces the ball off the FIRST one only: a seam between
// two bricks is thinner than the ball, so one pass can overlap two bricks, and
// flipping the velocity twice would cancel out and let the ball through
// (ISSUES.md #1, "neighbours"). Returns the destroyed bricks so the caller can
// score them.
export function brickHit(ball, bricks) {
  const hit = [];
  let bounced = false;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    hit.push(brick);
    if (!bounced) {
      bounceOff(ball, brick);
      bounced = true;
    }
  }
  return hit;
}

// Bounces the ball off one brick, per ISSUES.md #1: the face with the smaller
// penetration is the face that was hit — flip `vy` on a top/bottom hit, `vx`
// on a side hit, and leave the other component exactly as it was. Equal
// penetrations on both axes mean a diagonal (corner) hit: flip both. The ball
// is also pushed back out of the brick so it cannot re-collide on the next
// frame and re-flip forever (sticky bounce).
function bounceOff(ball, brick) {
  // How deep the ball's box sinks past each of the brick's four faces.
  const left = ball.x + ball.r - brick.x;
  const right = brick.x + brick.w - (ball.x - ball.r);
  const top = ball.y + ball.r - brick.y;
  const bottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(left, right);
  const penY = Math.min(top, bottom);

  // The smaller penetration names the hit axis; equal means a corner hit.
  const flipX = penX <= penY;
  const flipY = penY <= penX;

  if (flipX) {
    if (left < right) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  }
  if (flipY) {
    if (top < bottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

